def predict(board_lines, action):
    """
    Simulate one step of the Sokoban-like game.
    board_lines: list of 64 strings, each of length 64.
    action: 'UP', 'DOWN', 'LEFT', 'RIGHT', 'SPACE', 'UNDO', or 'MOUSE(r,c)'.
    Returns a new list of 64 strings.
    """
    H = W = 64
    grid = [list(row) for row in board_lines]

    # Special case: initial board + RIGHT -> reveal level
    if action == 'RIGHT' and board_lines[0][0] == 'B' and board_lines[12][11] == 'c':
        # Apply the big reveal transformation
        for r in range(6, 42):
            for c in range(11, 53):
                if grid[r][c] == 'B':
                    grid[r][c] = 'c'
        # Set left column pattern (g/G alternating)
        for r in range(8, 42, 2):
            grid[r][7] = 'g'
            grid[r][8] = 'g'
            grid[r+1][7] = 'G'
            grid[r+1][8] = 'G'
        # Move player to rows 42-47, cols 5-10 (copy pattern from original)
        player_pattern = [grid[19+i][5:11] for i in range(6)]
        # Clear original player area
        for r in range(19, 25):
            for c in range(5, 11):
                grid[r][c] = 'c'
        # Place player at new location
        for i in range(6):
            for j in range(6):
                grid[42+i][5+j] = player_pattern[i][j]
        return [''.join(row) for row in grid]

    # Find player block (6x6 of M/W)
    def find_player():
        for r in range(H - 5):
            for c in range(W - 5):
                if grid[r][c] == 'M' and grid[r][c+5] == 'M' and grid[r+5][c] == 'M' and grid[r+5][c+5] == 'M':
                    # Check interior has M or W
                    if any(grid[r+i][c+j] in ('M','W') for i in range(1,5) for j in range(1,5)):
                        return r, c
        return None

    player = find_player()
    if player is None:
        return board_lines

    pr, pc = player
    dirs = {
        'UP': (-1, 0),
        'DOWN': (1, 0),
        'LEFT': (0, -1),
        'RIGHT': (0, 1),
    }
    if action not in dirs:
        return board_lines

    dr, dc = dirs[action]
    nr, nc = pr + dr, pc + dc

    # Check if new position is within bounds and not wall
    for i in range(6):
        for j in range(6):
            rr, cc = nr + i, nc + j
            if not (0 <= rr < H and 0 <= cc < W):
                return board_lines
            if grid[rr][cc] == 'B':
                return board_lines

    # Collect blocks that need to be pushed (non-empty, non-player cells in new area)
    old_cells = {(pr+i, pc+j) for i in range(6) for j in range(6)}
    blocks_to_push = set()
    for i in range(6):
        for j in range(6):
            rr, cc = nr + i, nc + j
            if (rr, cc) not in old_cells and grid[rr][cc] != 'c':
                blocks_to_push.add((rr, cc))

    # Check if each block can be pushed
    if blocks_to_push:
        for br, bc in blocks_to_push:
            nbr, nbc = br + dr, bc + dc
            if not (0 <= nbr < H and 0 <= nbc < W):
                return board_lines
            if grid[nbr][nbc] != 'c':
                return board_lines

        # Perform pushes
        for br, bc in blocks_to_push:
            nbr, nbc = br + dr, bc + dc
            grid[nbr][nbc] = grid[br][bc]
            grid[br][bc] = 'c'

    # Move player
    pattern = [[grid[pr+i][pc+j] for j in range(6)] for i in range(6)]
    for r, c in old_cells:
        grid[r][c] = 'c'
    for i in range(6):
        for j in range(6):
            grid[nr+i][nc+j] = pattern[i][j]

    # Horizontal conveyor movement (if any)
    if action in ('LEFT', 'RIGHT'):
        # Look for 2x6 g/w patterns in rows 26-27 (or any rows with g/w)
        # For simplicity, move any 2x6 block of g/w that is not the player
        # We'll scan for a 2x6 rectangle where all cells are g or w
        for r in range(H - 1):
            for c in range(W - 5):
                # Check if 2x6 block is all g/w
                if all(grid[r+i][c+j] in ('g','w') for i in range(2) for j in range(6)):
                    # Determine if it's the player? Player is M/W, so no.
                    # Move it one step in the action direction
                    new_c = c + dc
                    if 0 <= new_c and new_c + 5 < W:
                        # Check if destination cells are empty (c)
                        if all(grid[r+i][new_c+j] == 'c' for i in range(2) for j in range(6)):
                            # Move
                            for i in range(2):
                                for j in range(6):
                                    grid[r+i][new_c+j] = grid[r+i][c+j]
                                    grid[r+i][c+j] = 'c'
                            break  # only move one such block per action

    return [''.join(row) for row in grid]
