    Moves each block by 5 cells in the given direction if the path is clear.
    """
    grid = [list(row) for row in board_lines]
    step = 5

    if action == 'UP':
        dr, dc = -1, 0
        rows = range(64)
        cols = range(64)
    elif action == 'DOWN':
        dr, dc = 1, 0
        rows = range(63, -1, -1)
        cols = range(64)
    elif action == 'LEFT':
        dr, dc = 0, -1
        rows = range(64)
        cols = range(64)
    elif action == 'RIGHT':
        dr, dc = 0, 1
        rows = range(64)
        cols = range(63, -1, -1)
    else:
        return board_lines

    for r in rows:
        for c in cols:
            if grid[r][c] != 'c':
                # Try to move `step` cells in the direction
                nr, nc = r + dr * step, c + dc * step
                if 0 <= nr < 64 and 0 <= nc < 64:
                    # Check if all intermediate cells are empty
                    clear = True
                    for i in range(1, step + 1):
                        rr = r + dr * i
                        cc = c + dc * i
                        if grid[rr][cc] != 'c':
                            clear = False
                            break
                    if clear:
                        grid[nr][nc] = grid[r][c]
                        grid[r][c] = 'c'

    return [''.join(row) for row in grid]

