    for top, left in INTERACTIVE_BLOCKS:
        if top <= r < top + 6 and left <= c < left + 6:
            return True
    return False

def reset_board():
    # Start with all 'c'
    grid = [['c'] * 64 for _ in range(64)]

    # Fill interactive blocks with 'b'
    for top, left in INTERACTIVE_BLOCKS:
        for r in range(top, top + 6):
            for c in range(left, left + 6):
                grid[r][c] = 'b'

    # Special last-4-column pattern
    for r in range(4):
        for c in range(60, 64):
            grid[r][c] = 'b'
    for r in range(4, 8):
        for c in range(60, 64):
            grid[r][c] = 'O'

    # Row 63 all 'O'
    for c in range(64):
        grid[63][c] = 'O'

    return [''.join(row) for row in grid]

def predict(board_lines, action):
    if not action.startswith("MOUSE"):
        return board_lines

    m = re.match(r"MOUSE\(row=(\d+), col=(\d+)\)", action)
    if not m:
        return board_lines

    r = int(m.group(1))
    c = int(m.group(2))

    # If click is not on an interactive block, reset
    if not is_interactive(r, c):
        return reset_board()

    # Convert to mutable grid
    grid = [list(line) for line in board_lines]

    # Find the block containing (r,c) and toggle it
    for top, left in INTERACTIVE_BLOCKS:
        if top <= r < top + 6 and left <= c < left + 6:
            # The block is guaranteed to be uniform b or O
            new_color = 'O' if grid[top][left] == 'b' else 'b'
            for rr in range(top, top + 6):
                for cc in range(left, left + 6):
                    grid[rr][cc] = new_color

            # Update bottom row: change two rightmost O's to Y
            row63 = grid[63]
            o_indices = [idx for idx, ch in enumerate(row63) if ch == 'O']
            if len(o_indices) >= 2:
                row63[o_indices[-1]] = 'Y'
                row63[o_indices[-2]] = 'Y'

